class Solution {
public:
    long long minSumSquareDiff(std::vector<int>& nums1, std::vector<int>& nums2, int k1, int k2) {
        long long k = (long long)k1 + k2;
        int n = nums1.size();
        int max_d = 0;
        std::vector<int> diffs(n);
        long long total_diff = 0;
        for (int i = 0; i < n; ++i) {
            diffs[i] = std::abs(nums1[i] - nums2[i]);
            max_d = std::max(max_d, diffs[i]);
            total_diff += diffs[i];
        }
        if (total_diff <= k) return 0;
        std::vector<int> count(max_d + 1, 0);
        for (int d : diffs) count[d]++;
        for (int d = max_d; d > 0; --d) {
            if (count[d] > 0) {
                long long take = std::min(k, (long long)count[d]);
                count[d - 1] += take;
                count[d] -= take;
                k -= take;
                if (k == 0) break;
            }
        }
        long long ans = 0;
        for (int d = 1; d <= max_d; ++d) {
            ans += (long long)count[d] * d * d;
        }
        return ans;
    }
};

class Solution {
    public long minSumSquareDiff(int[] nums1, int[] nums2, int k1, int k2) {
        long k = (long) k1 + k2;
        int n = nums1.length;
        int maxD = 0;
        int[] diffs = new int[n];
        long totalDiff = 0;
        for (int i = 0; i < n; ++i) {
            diffs[i] = Math.abs(nums1[i] - nums2[i]);
            maxD = Math.max(maxD, diffs[i]);
            totalDiff += diffs[i];
        }
        if (totalDiff <= k) return 0;
        int[] count = new int[maxD + 1];
        for (int d : diffs) count[d]++;
        for (int d = maxD; d > 0; --d) {
            if (count[d] > 0) {
                long take = Math.min(k, (long) count[d]);
                count[d - 1] += (int) take;
                count[d] -= (int) take;
                k -= take;
                if (k == 0) break;
            }
        }
        long ans = 0;
        for (int d = 1; d <= maxD; ++d) {
            ans += (long) count[d] * d * d;
        }
        return ans;
    }
}

var minSumSquareDiff = function(nums1, nums2, k1, k2) {
    let k = BigInt(k1 + k2);
    const n = nums1.length;
    let maxD = 0;
    const diffs = new Array(n);
    let totalDiff = 0n;
    for (let i = 0; i < n; ++i) {
        diffs[i] = Math.abs(nums1[i] - nums2[i]);
        maxD = Math.max(maxD, diffs[i]);
        totalDiff += BigInt(diffs[i]);
    }
    if (totalDiff <= k) return 0;
    const count = new Array(maxD + 1).fill(0n);
    for (const d of diffs) count[d] += 1n;
    for (let d = maxD; d > 0; --d) {
        if (count[d] > 0n) {
            const take = k < count[d] ? k : count[d];
            count[d - 1] += take;
            count[d] -= take;
            k -= take;
            if (k === 0n) break;
        }
    }
    let ans = 0n;
    for (let d = 1; d <= maxD; ++d) {
        ans += count[d] * BigInt(d) * BigInt(d);
    }
    return Number(ans);
};
